import {
    Mesh,
    PlaneGeometry,
    Group,
    Object3D,
    DoubleSide,
    Color,
    Texture,
    MeshStandardNodeMaterial
} from 'three/webgpu';
import {
    texture,
    uv,
    mix,
    color,
    contrast,
    saturation,
    luminance,
    mul,
    add,
    sub,
    pow,
    clamp,
    sin,
    cos,
    vec2,
    vec3,
    normalize,
    dot,
    fresnel,
    positionWorld,
    normalWorld,
    reflect,
    viewDirectionWorld
} from 'three/tsl';
import { gsap } from 'gsap';
import '@/primitives';
import '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {{imageUrl:string, depthMapUrl:string}} assets
 * @property {{cinematicPrimitives:Array<{name:string,params:any}>}} cinematicPrimitives
 * @property {Array<string>} textContent
 * @property {Object} placement
 */

/**
 * @typedef {Object} NodeContext
 * @property {(url:string)=>Texture} textureLoader
 * @property {{[key:string]:(target:Object3D,params:any)=>void}} primitives
 * @property {{createText:(content:string,style:any,atlasRegion:any)=>Object3D}} fontAtlas
 */

/**
 * Create the hero composite node.
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
    // -----------------------------------------------------------------------
    // Geometry & Textures
    // -----------------------------------------------------------------------
    const WIDTH = 4.0;
    const HEIGHT = 2.5;
    const SEGMENTS = 64;

    const geometry = new PlaneGeometry(WIDTH, HEIGHT, SEGMENTS, SEGMENTS);
    const colorTex = ctx.textureLoader(config.assets.imageUrl);
    const depthTex = ctx.textureLoader(config.assets.depthMapUrl);

    // -----------------------------------------------------------------------
    // Material with displacement and colour grading
    // -----------------------------------------------------------------------
    const texNode = texture(colorTex);
    const depthNode = texture(depthTex);

    // Simple colour grading: desaturate -8% (preserve red), contrast +12%
    const desatNode = saturation(texNode, 0.92);
    const contrastNode = contrast(desatNode, 1.12);
    const gradedNode = contrastNode; // placeholder for further grading steps

    const material = new MeshStandardNodeMaterial({
        mapNode: gradedNode,
        displacementNode: depthNode,
        displacementScale: 0.18,
        side: DoubleSide,
        transparent: true,
        depthWrite: true,
        opacity: 0
    });

    // -----------------------------------------------------------------------
    // Main Plane Mesh
    // -----------------------------------------------------------------------
    const plane = new Mesh(geometry, material);
    plane.position.set(0, 0, 0);
    plane.rotation.set(0, 0, 0);
    plane.scale.set(1, 1, 1);

    // -----------------------------------------------------------------------
    // Bottom Scrim Gradient
    // -----------------------------------------------------------------------
    const scrimGeometry = new PlaneGeometry(WIDTH, HEIGHT, 1, 1);
    const uvNode = uv();
    const gradientNode = mix(
        color('#0b0b1000'),
        color('#0b0b10eb'),
        uvNode.y
    );
    const scrimMaterial = new MeshStandardNodeMaterial({
        colorNode: gradientNode,
        side: DoubleSide,
        transparent: true,
        depthWrite: false
    });
    const scrim = new Mesh(scrimGeometry, scrimMaterial);
    scrim.position.set(0, -HEIGHT / 2 + 0.25, 0.001); // sit just above the plane
    scrim.rotation.set(0, 0, 0);
    scrim.scale.set(1, 1, 1);

    // -----------------------------------------------------------------------
    // Caption Block (text)
    // -----------------------------------------------------------------------
    const captionGroup = new Group();

    // Padding
    const PAD = 0.5; // 0.5 scene units (2 * base unit)

    // Helper to create a text mesh
    const createTextMesh = (content, style) => {
        const mesh = ctx.fontAtlas.createText(content, {
            family: style.family,
            size: style.fontSize / 100, // convert px to scene unit scale (approx)
            weight: style.fontWeight,
            letterSpacing: style.letterSpacing,
            lineHeight: style.lineHeight,
            color: style.color || '#e8ecf2'
        });
        return mesh;
    };

    // Text styles based on design tokens
    const styles = {
        kicker: {
            family: 'JetBrains Mono',
            fontSize: 9,
            fontWeight: 700,
            letterSpacing: 0.12,
            lineHeight: 1.2,
            color: '#e8ecf2'
        },
        headline: {
            family: 'Lora',
            fontSize: 34,
            fontWeight: 600,
            letterSpacing: -0.01,
            lineHeight: 1.1,
            color: '#e8ecf2'
        },
        body: {
            family: 'JetBrains Mono',
            fontSize: 13,
            fontWeight: 400,
            letterSpacing: 0,
            lineHeight: 1.5,
            color: '#e8ecf2'
        },
        caption: {
            family: 'JetBrains Mono',
            fontSize: 9,
            fontWeight: 400,
            letterSpacing: 0.12,
            lineHeight: 1.4,
            color: '#e8ecf2'
        },
        accentBar: {
            color: '#ff2a38'
        }
    };

    // Create text meshes
    const kickerMesh = createTextMesh('NOVA ATELIER / GENEVA', styles.kicker);
    const headlineMesh = createTextMesh('Time, Machined.', styles.headline);
    const bodyMesh = createTextMesh('Every case begins as a single billet of 904L steel.', styles.body);
    const captionMesh = createTextMesh('CALIBRE NA-01 / 72 HOUR RESERVE', styles.caption);

    // Accent bar mesh (simple thin plane)
    const barWidth = 0.75;
    const barHeight = 0.02;
    const barGeometry = new PlaneGeometry(barWidth, barHeight);
    const barMaterial = new MeshStandardNodeMaterial({
        colorNode: color('#ff2a38'),
        emissiveNode: mul(color('#ff2a38'), 1.8),
        side: DoubleSide,
        transparent: true,
        depthWrite: false
    });
    const accentBar = new Mesh(barGeometry, barMaterial);

    // Positioning inside caption block
    const startX = -WIDTH / 2 + PAD;
    let cursorY = -HEIGHT / 2 + PAD;

    kickerMesh.position.set(startX, cursorY, 0);
    cursorY += styles.kicker.fontSize / 100 * styles.kicker.lineHeight + 0.025; // baseline rhythm

    headlineMesh.position.set(startX, cursorY, 0);
    cursorY += styles.headline.fontSize / 100 * styles.headline.lineHeight + 0.025;

    // Accent bar
    accentBar.position.set(startX + barWidth / 2, cursorY, 0);
    cursorY += barHeight + 0.025;

    bodyMesh.position.set(startX, cursorY, 0);
    cursorY += styles.body.fontSize / 100 * styles.body.lineHeight + 0.025;

    captionMesh.position.set(startX, cursorY, 0);

    // Assemble caption group
    captionGroup.add(kickerMesh);
    captionGroup.add(headlineMesh);
    captionGroup.add(accentBar);
    captionGroup.add(bodyMesh);
    captionGroup.add(captionMesh);
    captionGroup.position.set(0, 0, 0.002); // slightly above the scrim

    // -----------------------------------------------------------------------
    // Root Group
    // -----------------------------------------------------------------------
    const root = new Group();
    root.add(plane);
    root.add(scrim);
    root.add(captionGroup);
    root.position.set(0, 0, 0);
    root.rotation.set(0, 0, 0);
    root.scale.set(1, 1, 1);

    // -----------------------------------------------------------------------
    // Apply Cinematic Primitives
    // -----------------------------------------------------------------------
    if (Array.isArray(config.cinematicPrimitives)) {
        config.cinematicPrimitives.forEach(primitive => {
            const fn = ctx.primitives[primitive.name];
            if (typeof fn === 'function') {
                fn(root, primitive.params);
            }
        });
    }

    // -----------------------------------------------------------------------
    // Animations (GSAP)
    // -----------------------------------------------------------------------
    const timeline = gsap.timeline({ paused: true });

    // Plate mount fade-in
    timeline.from(
        plane.material,
        {
            opacity: 0,
            duration: 0.5,
            ease: 'cubic-bezier(0.25,0.46,0.45,0.94)'
        },
        0
    );

    // Caption block rise-in after 120ms
    timeline.from(
        captionGroup.position,
        {
            y: '+=' + 0.4,
            duration: 0.7,
            ease: 'cubic-bezier(0.215,0.61,0.355,1)'
        },
        '+=0.12'
    );

    timeline.play();

    // -----------------------------------------------------------------------
    // Cleanup
    // -----------------------------------------------------------------------
    root.userData.handlers = {};

    root.userData.cleanup = () => {
        timeline.kill();
        geometry.dispose();
        scrimGeometry.dispose();
        barGeometry.dispose();
        if (material.map) material.map.dispose();
        if (material.displacementMap) material.displacementMap.dispose();
        material.dispose();
        scrimMaterial.dispose();
        barMaterial.dispose();
        // Assuming ctx.fontAtlas provides a dispose method per mesh
        [kickerMesh, headlineMesh, bodyMesh, captionMesh].forEach(m => {
            if (m.geometry) m.geometry.dispose();
            if (m.material) m.material.dispose();
        });
    };

    return root;
}
